{"language":"TypeScript","fileName":"http-api-gateway.ts","entrypoint":"execute","updatedAt":"2026-11-04T05:40:03.471Z","source":"// HTTP API Gateway
// Front-door service that terminates HTTP(S), routes requests to backends, and applies validation, rate limiting and access logging at the edge.

export async function execute(context: Record<string, unknown>) {
  const capabilities = ["http_routing","tls_termination","reverse_proxy"];
  const requirements = ["network_listener","thread_pool"];

  return {
    elementId: 'orb-http-gateway',
    capabilities,
    requirements,
    context,
    status: 'ready'
  };
}
"}

